files.content:
[hidden] { display: none !important; }

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  background: #1a1a2e;
  color: #e0e0e0;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: #16213e;
  border-radius: 24px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 24px;
  color: #e94560;
  letter-spacing: 1px;
}

.settings {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}

.settings label {
  font-size: 1rem;
  text-align: left;
  color: #a0a0b0;
}

.settings input {
  font-size: 1.2rem;
  padding: 12px 16px;
  border: 2px solid #0f3460;
  border-radius: 12px;
  background: #1a1a2e;
  color: #e0e0e0;
  width: 100%;
  transition: border-color 0.2s;
}

.settings input:focus {
  outline: none;
  border-color: #e94560;
}

button {
  font-size: 1.2rem;
  padding: 14px 24px;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  font-weight: 600;
  transition: background 0.2s, transform 0.1s;
  width: 100%;
}

button.primary {
  background: #e94560;
  color: #fff;
}

button.primary:hover {
  background: #c73650;
}

button.primary:active {
  transform: scale(0.98);
}

button.secondary {
  background: #0f3460;
  color: #e0e0e0;
}

button.secondary:hover {
  background: #1a4a7a;
}

button.secondary:active {
  transform: scale(0.98);
}

button:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.display {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 32px 0;
}

.phase {
  font-size: 2rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #e94560;
}

.timer {
  font-size: 4.5rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: #fff;
  line-height: 1;
}

.round {
  font-size: 1.2rem;
  color: #a0a0b0;
}

.complete {
  padding: 32px 0;
}

.complete p {
  font-size: 1.8rem;
  font-weight: 700;
  color: #e94560;
  margin-bottom: 24px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .timer {
    font-size: 3.5rem;
  }
}

const workInput = document.getElementById('work');
const restInput = document.getElementById('rest');
const roundsInput = document.getElementById('rounds');
const startBtn = document.getElementById('startBtn');
const display = document.getElementById('display');
const phaseLabel = document.getElementById('phaseLabel');
const timerDisplay = document.getElementById('timerDisplay');
const roundLabel = document.getElementById('roundLabel');
const complete = document.getElementById('complete');
const resetBtn = document.getElementById('resetBtn');

let timerId = null;
let currentPhase = 'work';
let remaining = 0;
let currentRound = 1;
let totalRounds = 0;
let workSeconds = 0;
let restSeconds = 0;

function updateDisplay() {
  phaseLabel.textContent = currentPhase === 'work' ? 'Work' : 'Rest';
  timerDisplay.textContent = remaining.toString().padStart(2, '0');
  roundLabel.textContent = `Round ${currentRound} / ${totalRounds}`;
}

function tick() {
  remaining--;
  if (remaining > 0) {
    updateDisplay();
    return;
  }
  // phase ended
  if (currentPhase === 'work') {
    if (currentRound < totalRounds) {
      currentPhase = 'rest';
      remaining = restSeconds;
      updateDisplay();
    } else {
      // last round work done -> complete
      finishWorkout();
    }
  } else {
    // rest ended -> next round work
    currentRound++;
    currentPhase = 'work';
    remaining = workSeconds;
    updateDisplay();
  }
}

function startWorkout() {
  workSeconds = Math.max(1, parseInt(workInput.value, 10) || 30);
  restSeconds = Math.max(1, parseInt(restInput.value, 10) || 15);
  totalRounds = Math.max(1, parseInt(roundsInput.value, 10) || 3);

  currentPhase = 'work';
  remaining = workSeconds;
  currentRound = 1;

  display.hidden = false;
  complete.hidden = true;
  startBtn.disabled = true;
  workInput.disabled = true;
  restInput.disabled = true;
  roundsInput.disabled = true;

  updateDisplay();
  timerId = setInterval(tick, 1000);
}

function finishWorkout() {
  clearInterval(timerId);
  timerId = null;
  display.hidden = true;
  complete.hidden = false;
  startBtn.disabled = false;
  workInput.disabled = false;
  restInput.disabled = false;
  roundsInput.disabled = false;
}

function reset() {
  clearInterval(timerId);
  timerId = null;
  display.hidden = true;
  complete.hidden = true;
  startBtn.disabled = false;
  workInput.disabled = false;
  restInput.disabled = false;
  roundsInput.disabled = false;
}

startBtn.addEventListener('click', startWorkout);
resetBtn.addEventListener('click', reset);
